<!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF8">
    <meta name="viewport" content="width=devicewidth, initialscale=1.0, userscalable=no">
    <title>JADE  Deep Discovery AI Platform</title>
    <link rel="stylesheet" href="">
    <link rel="stylesheet" href="">
    <script src=""></script>
    <script src=""></script>
    <! Hozzáadva: Three.js a 3D háttérhez >
    <script src=""></script>
    <style>
        /  Alap stílusok és változók (UI Frissítés 3D Liquid)  /
        @import url('');

        :root {
            primary: 0A84FF; / Fő kék szín /
            secondary: 39FF14; / Új NEON ZÖLD kiemelő /
            accent: 0A84FF; / Interaktív kék /
            primarygradient: lineargradient(135deg, var(primary), var(secondary)); / KékNeonZöld Gradiens /

            bg: 000000; / Tiszta fekete háttér /
            surface: rgba(10, 10, 10, 0.7); / Sötét "Black Glass" /
            glass: rgba(255, 255, 255, 0.05);
            glassstrong: rgba(255, 255, 255, 0.1);
            border: rgba(60, 68, 89, 0.4); / Finom szegély /
            borderglow: rgba(10, 132, 255, 0.5); / Kék fénylés /
            text: f0f0f0;
            textmuted: 94a3b8;
            radius: 16px;
            shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
            transitioncurve: cubicbezier(0.25, 0.8, 0.25, 1);
        }

         {
            margin: 0;
            padding: 0;
            boxsizing: borderbox;
            webkittaphighlightcolor: transparent;
        }

        html {
            height: 100%;
            height: webkitfillavailable;
            scrollbehavior: smooth;
            webkitoverflowscrolling: touch;
        }

        body {
            fontfamily: 'Inter', sansserif;
            background: var(bg);
            color: var(text);
            minheight: 100vh;
            minheight: webkitfillavailable;
            overflowx: hidden;
            webkitfontsmoothing: antialiased;
            mozosxfontsmoothing: grayscale;
        }

        / Új 3D Liquid Háttér Stílus /
        liquidbackground {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            zindex: 1; / A tartalom mögött van /
            display: block;
        }


        @supports (padding: max(0px)) {
            body {
                paddingleft: max(0px, env(safeareainsetleft));
                paddingright: max(0px, env(safeareainsetright));
            }
        }

        ::webkitscrollbar { width: 4px; }
        ::webkitscrollbartrack { background: transparent; }
        ::webkitscrollbarthumb {
            background: var(glassstrong);
            borderradius: 10px;
            border: 1px solid var(border);
        }

        / Régi Aurora háttér eltávolítva /
        .aurorabackground { display: none; }

        /  Fő elrendezés  /
        .container { 
            display: flex; 
            minheight: 100vh; 
            minheight: webkitfillavailable;
            position: relative; 
            zindex: 2; / A háttér fölött /
        }

        /  Oldalsáv (Sidebar)  /
        .sidebar {
            width: 260px;
            background: var(surface);
            backdropfilter: blur(40px) saturate(180%);
            borderright: 1px solid var(border);
            overflowy: auto;
            position: fixed;
            height: 100vh;
            height: webkitfillavailable;
            zindex: 1000;
            transform: translateX(100%);
            transition: transform 0.4s var(transitioncurve);
            display: flex;
            flexdirection: column;
        }
        .sidebar.open { transform: translateX(0); }

        .sidebaroverlay {
            position: fixed;
            top: 0; left: 0;
            width: 100vw; height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdropfilter: blur(10px);
            zindex: 999;
            opacity: 0;
            visibility: hidden;
            transition: all 0.4s ease;
        }
        .sidebaroverlay.active { opacity: 1; visibility: visible; }

        .sidebarheader {
            padding: 16px 12px;
            borderbottom: 1px solid var(border);
        }
        .logo { display: flex; alignitems: center; gap: 8px; marginbottom: 16px; }
        .logoicon {
            width: 32px; height: 32px;
            background: var(primarygradient); / KékNeonZöld Gradiens /
            borderradius: 8px;
            display: flex; alignitems: center; justifycontent: center;
            fontsize: 1.2rem; fontweight: 800; color: fff;
            boxshadow: 0 4px 20px rgba(10, 132, 255, 0.3), 0 4px 20px rgba(57, 255, 20, 0.3); / Új árnyék /
            transition: transform 0.3s var(transitioncurve);
        }
        .logo:hover .logoicon { transform: rotate(10deg) scale(1.1); }
        .logotext h1 {
            fontsize: 1.2rem; fontweight: 800;
            color: var(text);
            lineheight: 1.1;
        }
        .logotext p { fontsize: 0.7rem; color: var(textmuted); margintop: 2px; fontweight: 500; }

        .newchatbtn {
            width: 100%;
            background: var(primarygradient); / KékNeonZöld Gradiens /
            border: none;
            color: ffffff;
            borderradius: 10px;
            padding: 10px 12px;
            fontweight: 600; fontsize: 0.8rem;
            cursor: pointer;
            display: flex; alignitems: center; justifycontent: center; gap: 6px;
            transition: all 0.3s var(transitioncurve);
            boxshadow: 0 6px 20px rgba(10, 132, 255, 0.3), 0 6px 20px rgba(57, 255, 20, 0.3); / Új árnyék /
        }
        .newchatbtn:hover, .newchatbtn:active {
            transform: translateY(2px);
            filter: brightness(1.1);
            boxshadow: 0 8px 25px rgba(10, 132, 255, 0.4), 0 8px 25px rgba(57, 255, 20, 0.4);
        }

        .sidebarcontent { padding: 12px; flexgrow: 1; overflowy: auto; }
        .sidebarfooter { padding: 12px; bordertop: 1px solid var(border); }
        .madeby { fontsize: 0.7rem; color: var(textmuted); textalign: center; }

        .servicecategory { marginbottom: 16px; }
        .categoryheader {
            background: var(glass);
            border: 1px solid var(border);
            borderradius: var(radius);
            padding: 8px 12px;
            cursor: pointer;
            display: flex; alignitems: center; justifycontent: spacebetween;
            marginbottom: 6px;
            transition: all 0.3s var(transitioncurve);
            minheight: 40px;
        }
        .categoryheader .fachevrondown { transition: transform 0.3s var(transitioncurve); }
        .categoryheader:hover, .categoryheader:active {
            background: var(glassstrong);
            bordercolor: var(accent);
            transform: translateY(2px);
        }
        .categorytitle { display: flex; alignitems: center; gap: 8px; fontweight: 600; fontsize: 0.8rem; }
        .categorytitle i { color: var(accent); }
        .categoryservices {
            display: grid;
            gridtemplaterows: 0fr;
            transition: gridtemplaterows 0.4s easeout;
        }
        .categoryservices > div { overflow: hidden; }
        .categoryservices.open { gridtemplaterows: 1fr; }

        .serviceitem {
            background: transparent;
            border: 1px solid transparent;
            borderradius: var(radius);
            padding: 8px 12px; marginbottom: 4px; cursor: pointer;
            transition: all 0.3s var(transitioncurve);
            display: flex; alignitems: center; gap: 8px;
            marginleft: 0;
            borderleft: 3px solid var(border);
            minheight: 44px;
        }
        .serviceitem:hover, .serviceitem:active {
            background: var(glassstrong);
            borderleftcolor: var(accent);
            transform: translateX(4px);
            color: fff;
            boxshadow: 0 0 15px var(borderglow);
        }
        .serviceicon {
            width: 24px; height: 24px;
            background: lineargradient(135deg, var(glassstrong), var(glass));
            border: 1px solid var(border);
            borderradius: 6px;
            display: flex; alignitems: center; justifycontent: center;
            fontsize: 0.8rem; color: var(accent); flexshrink: 0;
            transition: all 0.3s var(transitioncurve);
        }
        .serviceitem:hover .serviceicon { 
            transform: scale(1.1); 
            color: var(accent); 
            bordercolor: var(accent); 
        }
        .serviceinfo h4 { fontsize: 0.75rem; fontweight: 600; marginbottom: 2px; }
        .serviceinfo p { fontsize: 0.7rem; color: var(textmuted); }

        /  Fő tartalom  /
        .maincontent {
            flex: 1; marginleft: 0;
            display: flex; flexdirection: column;
            transition: marginleft 0.4s var(transitioncurve);
            minheight: 100vh;
            minheight: webkitfillavailable;
        }
        .header {
            padding: 8px 16px;
            background: rgba(0, 0, 0, 0.6);
            backdropfilter: blur(30px) saturate(150%);
            borderbottom: 1px solid var(border);
            display: flex; alignitems: center; justifycontent: spacebetween;
            position: sticky; top: 0; zindex: 100;
            height: 56px;
        }
        .menutoggle {
            background: var(glassstrong);
            border: 1px solid var(border);
            borderradius: 8px; padding: 8px;
            color: var(text); cursor: pointer;
            transition: all 0.3s var(transitioncurve);
            fontsize: 0.9rem; width: 36px; height: 36px;
            display: flex; alignitems: center; justifycontent: center;
        }
        .menutoggle:hover, .menutoggle:active {
            background: var(glassstrong);
            bordercolor: var(accent);
            transform: scale(1.05);
        }
        .headertitle {
            fontsize: 1rem; fontweight: 700;
            color: var(text);
            textshadow: none;
        }

        /  Chat terület  /
        .chatarea { flex: 1; display: flex; flexdirection: column; overflow: hidden; }
        .messagescontainer { 
            flex: 1; 
            overflowy: auto; 
            padding: 16px; 
            scrollbehavior: smooth;
            overscrollbehavior: contain;
        }

        .welcomescreen {
            textalign: center; maxwidth: 500px;
            margin: 0 auto; padding: 30px 16px;
            display: flex; flexdirection: column; alignitems: center; justifycontent: center;
            height: 100%; animation: fadeIn 1s var(transitioncurve);
        }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .welcometitle {
            fontsize: 2.5rem; fontweight: 800; marginbottom: 1rem;
            color: var(text);
            textshadow: 0 0 30px var(borderglow);
        }
        .welcomesubtitle { fontsize: 1rem; color: var(textmuted); marginbottom: 2rem; lineheight: 1.6; }
        .startbtn {
            background: var(glassstrong);
            border: 1px solid var(border);
            borderradius: 10px;
            padding: 12px 24px; color: var(text);
            fontweight: 600; fontsize: 0.9rem; cursor: pointer;
            transition: all 0.3s var(transitioncurve);
            display: inlineflex; alignitems: center; gap: 8px;
            minheight: 44px;
        }
        .startbtn:hover, .startbtn:active {
            background: var(glassstrong);
            bordercolor: var(accent);
            transform: translateY(3px) scale(1.05);
        }

        .message { marginbottom: 16px; animation: messageSlideIn 0.5s var(transitioncurve); }
        @keyframes messageSlideIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

        .usermessage { display: flex; justifycontent: flexend; }
        .userbubble {
            background: var(primarygradient); / KékNeonZöld Gradiens /
            color: fff; padding: 10px 16px;
            borderradius: var(radius) var(radius) 4px var(radius);
            maxwidth: 85%; fontweight: 500; fontsize: 0.9rem; lineheight: 1.5;
            boxshadow: 0 5px 20px rgba(10, 132, 255, 0.2), 0 5px 20px rgba(57, 255, 20, 0.2); / Új árnyék /
        }
        .aimessage { display: flex; flexdirection: column; maxwidth: 95%; }
        .aicontent {
            background: var(surface);
            border: 1px solid var(border);
            borderradius: var(radius) 4px var(radius) var(radius);
            padding: 12px 16px; lineheight: 1.7; fontsize: 0.9rem;
        }
        .aicontent pre {
            background: 010409;
            border: 1px solid var(border);
            borderradius: 8px; padding: 12px; margin: 12px 0;
            fontsize: 0.8rem; overflowx: auto;
        }
        .aicontent code { fontfamily: 'SF Mono', 'Fira Code', 'Courier New', monospace; fontsize: 0.8rem; }

        .messageactions { display: flex; gap: 6px; margintop: 8px; marginleft: 8px; }
        .actionbtn {
            background: var(glass); border: 1px solid var(border);
            borderradius: 6px; padding: 4px 8px; color: var(textmuted);
            fontsize: 0.7rem; cursor: pointer;
            transition: all 0.3s var(transitioncurve);
            display: flex; alignitems: center; gap: 4px;
            minheight: 32px;
        }
        .actionbtn:hover, .actionbtn:active {
            background: var(glassstrong); color: var(text);
            bordercolor: var(accent); transform: translateY(2px);
        }

        /  Beviteli mező  /
        .inputarea {
            padding: 16px;
            background: transparent;
            backdropfilter: none;
            bordertop: 1px solid var(border);
            position: sticky; bottom: 0; zindex: 50;
        }

        @supports (padding: max(0px)) {
            .inputarea {
                paddingbottom: max(16px, env(safeareainsetbottom));
            }
        }

        .inputwrapper { 
            maxwidth: 1000px; 
            margin: 0 auto; 
            display: flex; 
            gap: 8px; 
            alignitems: flexend;
            background: var(surface);
            border: 1px solid var(border);
            borderradius: var(radius);
            padding: 8px;
            transition: all 0.3s var(transitioncurve);
        }
        .inputwrapper:focuswithin {
            bordercolor: var(accent);
            boxshadow: 0 0 20px var(borderglow);
        }

        .messageinput {
            flex: 1; 
            background: transparent;
            border: none;
            borderradius: 8px;
            padding: 10px 14px; color: var(text); fontsize: 0.9rem;
            resize: none; outline: none;
            transition: all 0.3s var(transitioncurve);
            minheight: 40px; maxheight: 120px;
            fontfamily: inherit; lineheight: 1.4;
        }
        .messageinput:focus {
            boxshadow: none;
        }
        .sendbtn {
            width: 40px; height: 40px;
            background: var(accent);
            border: none;
            borderradius: 12px;
            color: fff; fontsize: 1rem;
            cursor: pointer; transition: all 0.3s var(transitioncurve);
            display: flex; alignitems: center; justifycontent: center;
            boxshadow: 0 4px 15px var(borderglow);
            flexshrink: 0;
        }
        .sendbtn:hover, .sendbtn:active { 
            transform: scale(1.1); 
            boxshadow: 0 8px 25px rgba(10, 132, 255, 0.6); 
        }
        .sendbtn:disabled {
            opacity: 0.5; cursor: notallowed; transform: none;
            background: var(glassstrong); bordercolor: var(border);
            boxshadow: none;
        }

        /  Töltés és Visszajelzés  /
        .typingindicator { display: flex; gap: 6px; }
        .typingdot {
            width: 6px; height: 6px;
            borderradius: 50%;
            animation: typingbounce 1.4s infinite easeinout;
        }
        .typingdot:nthchild(1) { background: var(primary); }
        .typingdot:nthchild(2) { background: var(secondary); animationdelay: 0.2s; }
        .typingdot:nthchild(3) { background: var(primary); animationdelay: 0.4s; }

        @keyframes typingbounce {
            0%, 80%, 100% { transform: scale(0); }
            40% { transform: scale(1.0); }
        }

        / Deep Research Töltésjelző /
        .researchindicator {
            background: var(surface);
            border: 1px solid var(border);
            borderradius: var(radius); 
            padding: 24px;
            display: flex; flexdirection: column; alignitems: center; gap: 16px;
        }
        .researchindicator .spinner {
            width: 40px; height: 40px;
            border: 4px solid var(border);
            bordertopcolor: var(accent);
            borderradius: 50%;
            animation: spin 1s linear infinite;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        .researchindicator h4 { 
            fontweight: 600; 
            color: var(text); 
            fontsize: 1rem;
        }
        .researchindicator p { 
            fontsize: 0.9rem;
            color: var(textmuted); 
            textalign: center; 
        }

        /  Modális ablak (Modal)  /
        .modal {
            position: fixed; top: 0; left: 0;
            width: 100%; height: 100%;
            background: rgba(0, 0, 0, 0.8);
            backdropfilter: blur(15px);
            display: none; alignitems: center; justifycontent: center;
            zindex: 2000; opacity: 0;
            transition: opacity 0.3s ease; padding: 16px;
        }
        .modal.show { display: flex; opacity: 1; }
        .modalcontent {
            background: var(surface); border: 1px solid var(border);
            borderradius: var(radius); padding: 20px;
            maxwidth: 450px; width: 100%;
            maxheight: 90vh; overflowy: auto;
            backdropfilter: blur(40px) saturate(180%);
            transform: scale(0.95) translateY(20px);
            transition: transform 0.4s var(transitioncurve);
        }
        .modal.show .modalcontent { transform: scale(1) translateY(0); }
        .modalheader { display: flex; alignitems: center; justifycontent: spacebetween; marginbottom: 20px; }
        .modaltitle {
            fontsize: 1.2rem; fontweight: 700;
            color: var(text);
        }
        .closebtn {
            background: var(glassstrong); border: 1px solid var(border);
            borderradius: 50%; width: 32px; height: 32px;
            display: flex; alignitems: center; justifycontent: center;
            color: var(text); cursor: pointer;
            transition: all 0.3s var(transitioncurve);
        }
        .closebtn:hover, .closebtn:active { transform: scale(1.1) rotate(90deg); }
        .modalbody { display: flex; flexdirection: column; gap: 12px; }
        .modalbody label { fontweight: 500; color: var(textmuted); fontsize: 0.8rem; }
        .modalbody input, .modalbody textarea {
            background: var(glassstrong); border: 1px solid var(border);
            borderradius: 8px; padding: 10px; color: var(text);
            fontsize: 0.9rem; outline: none;
            transition: all 0.3s var(transitioncurve);
            fontfamily: inherit; resize: vertical;
        }
        .modalbody input:focus, .modalbody textarea:focus { bordercolor: var(accent); }
        .modalfooter { margintop: 20px; display: flex; justifycontent: flexend; }
        .modalsubmitbtn {
            background: var(accent); color: fff;
            border: none; borderradius: 8px;
            padding: 10px 20px; fontweight: 600; fontsize: 0.8rem;
            cursor: pointer; transition: all 0.3s var(transitioncurve);
            minheight: 40px;
        }
        .modalsubmitbtn:hover, .modalsubmitbtn:active { transform: translateY(2px); }

        /  Kutatási Eredmények és Dokumentumok  /
        .researchcomplete, .researcherror {
            background: var(surface);
            border: 1px solid var(border);
            borderradius: var(radius); padding: 20px; margin: 12px 0;
            backdropfilter: blur(10px);
        }
        .completionstats h3, .errortext h3 {
            fontweight: 700; marginbottom: 12px;
            color: var(text); fontsize: 1rem;
            display: flex; alignitems: center; gap: 8px;
        }
        .completionstats h3 { color: var(accent); }
        .statsgrid { display: grid; gridtemplatecolumns: repeat(autofit, minmax(100px, 1fr)); gap: 12px; marginbottom: 20px; }

        .statitem { 
            textalign: center; 
            background: var(glassstrong);
            padding: 16px; 
            borderradius: var(radius); 
            border: 1px solid var(border);
        }
        .statnumber { 
            display: block; 
            fontsize: 1.5rem; 
            fontweight: 700; 
            color: var(accent); 
        }
        .statlabel { fontsize: 0.7rem; color: var(textmuted); }

        .documentpreview {
            background: lineargradient(135deg, rgba(10, 132, 255, 0.1), rgba(10, 132, 255, 0.05));
            border: 1px solid var(accent); borderradius: 10px;
            padding: 16px; cursor: pointer; transition: all 0.3s ease;
            display: flex; alignitems: center; gap: 12px;
        }
        .documentpreview:hover {
            background: lineargradient(135deg, rgba(10, 132, 255, 0.2), rgba(10, 132, 255, 0.1));
            transform: translateY(3px); boxshadow: 0 5px 15px rgba(10, 132, 255, 0.2);
        }
        .documenticon { fontsize: 2rem; color: var(accent); flexshrink: 0; }
        .documentinfo h4 { margin: 0 0 4px 0; color: var(text); fontweight: 600; fontsize: 0.9rem; }
        .documentinfo p { margin: 0; color: var(textmuted); fontsize: 0.8rem; }
        .documentarrow { fontsize: 1.2rem; color: var(accent); marginleft: auto; flexshrink: 0; transition: transform 0.3s ease; }
        .documentpreview:hover .documentarrow { transform: translateX(5px); }

        .researcherror { bordercolor: ff3b30; }
        .errortext h3 { color: ff453a; }
        .erroricon { fontsize: 1rem; }

        .documentviewer {
            position: fixed; top: 0; left: 0;
            width: 100%; height: 100%;
            background: var(bg); zindex: 10000;
            display: none; flexdirection: column;
            animation: slideInFromRight 0.5s var(transitioncurve);
        }
        @keyframes slideInFromRight { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .documentviewer.show { display: flex; }
        .documentheader {
            background: rgba(0, 0, 0, 0.7);
            backdropfilter: blur(30px);
            padding: 1rem; borderbottom: 1px solid var(border);
            display: flex; alignitems: center; gap: 1rem; flexwrap: wrap;
        }
        .documentheader h2 { flex: 1; margin: 0; fontweight: 700; fontsize: 1.1rem; }
        .documentcontent { flex: 1; overflowy: auto; padding: 1.5rem; }
        .documentsection { marginbottom: 2.5rem; }
        .documentsection h3 {
            color: var(accent); borderbottom: 2px solid var(accent);
            paddingbottom: 0.5rem; marginbottom: 1rem; fontweight: 700; fontsize: 1rem;
        }
        .synthesiscontent { 
            lineheight: 1.7; 
            background: var(surface);
            padding: 1rem; 
            borderradius: 6px; 
            borderleft: 4px solid var(accent); 
        }
        .sourceitem {
            display: flex; gap: 0.8rem; padding: 0.8rem;
            background: var(surface);
            borderradius: 6px;
            marginbottom: 0.8rem; borderleft: 3px solid var(border);
            transition: all 0.3s ease;
        }
        .sourceitem:hover { borderleftcolor: var(accent); transform: translateX(5px); }
        .sourcenumber { color: var(accent); fontweight: bold; flexshrink: 0; }
        .sourcecontent h4 { margin: 0 0 0.5rem 0; fontsize: 0.9rem; }
        .sourcecontent a { color: var(accent); textdecoration: none; fontsize: 0.8rem; wordbreak: breakall; }
        .sourcecontent a:hover { textdecoration: underline; }
        .sourcedate { display: block; color: var(textmuted); fontsize: 0.7rem; margintop: 0.5rem; }

        / iOSszerű animációk és interakciók /
        .iosbounce {
            animation: iosBounce 0.3s easeout;
        }

        @keyframes iosBounce {
            0% { transform: scale(1); }
            50% { transform: scale(0.95); }
            100% { transform: scale(1); }
        }

        / Érintési visszajelzés /
        .touchfeedback {
            position: relative;
            overflow: hidden;
        }

        .touchfeedback::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            background: rgba(255, 255, 255, 0.3);
            borderradius: 50%;
            transform: translate(50%, 50%);
            transition: width 0.3s ease, height 0.3s ease;
            pointerevents: none;
        }

        .touchfeedback.active::before {
            width: 200px;
            height: 200px;
        }

        / Swipe indikátor /
        .swipeindicator {
            position: fixed;
            top: 50%;
            left: 10px;
            transform: translateY(50%);
            width: 4px;
            height: 60px;
            background: var(accent);
            borderradius: 2px;
            opacity: 0;
            transition: opacity 0.3s ease;
            zindex: 1000;
        }

        .swipeindicator.show {
            opacity: 0.7;
        }

        / Pulltorefresh indikátor /
        .pullrefresh {
            position: fixed;
            top: 60px;
            left: 50%;
            transform: translateX(50%);
            width: 40px;
            height: 40px;
            background: var(glass);
            borderradius: 50%;
            display: flex;
            alignitems: center;
            justifycontent: center;
            transition: top 0.3s ease;
