            researchState: null
        };
        const API_BASE_URL = '/api';

        //  DOM Elemek Gyors Elérése 
        const getEl = (id) => document.getElementById(id);

        //  ÚJ 3D FOLYÉKONY HÁTTÉR 
        // (A "palace" kódja előtt definiálva, de a DOMContentLoadedben hívva)
        let scene, camera, renderer, plane, lightBlue, lightGreen;
        let time = 0;

        function initLiquidBackground() {
            try {
                scene = new THREE.Scene();
                camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
                camera.position.z = 1.5;

                renderer = new THREE.WebGLRenderer({ canvas: getEl('liquidbackground'), alpha: true });
                renderer.setSize(window.innerWidth, window.innerHeight);

                // A "folyékony" sík
                const geometry = new THREE.PlaneGeometry(5, 5, 100, 100);
                const material = new THREE.MeshStandardMaterial({
                    color: 0x000000, // Fekete alap, a fények adják a színt
                    metalness: 0.9,
                    roughness: 0.3,
                });
                plane = new THREE.Mesh(geometry, material);
                scene.add(plane);

                // Fények
                lightBlue = new THREE.PointLight(0x0A84FF, 5, 10);
                lightBlue.position.set(1, 1, 1);
                scene.add(lightBlue);

                lightGreen = new THREE.PointLight(0x39FF14, 5, 10);
                lightGreen.position.set(1, 1, 1);
                scene.add(lightGreen);

                // Eszközkezelő az átméretezéshez
                window.addEventListener('resize', onWindowResize, false);

                // Animáció indítása
                animate();
            } catch (e) {
                console.error("3D background initialization failed:", e);
                // Hiba esetén elrejti a canvast, hogy ne legyen üres fekete blokk
                getEl('liquidbackground').style.display = 'none';
            }
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function animate() {
            requestAnimationFrame(animate);
            time += 0.002; // Nagyon lassú animáció

            // Fények lassú mozgatása
            lightBlue.position.x = Math.sin(time  0.3)  2;
            lightBlue.position.y = Math.cos(time  0.2)  2;
            lightGreen.position.x = Math.sin(time  0.2)  2;
            lightGreen.position.y = Math.cos(time  0.3)  2;

            // Sík pontjainak (vertices) mozgatása a "liquid" effektért
            const positions = plane.geometry.attributes.position.array;
            for (let i = 0; i < positions.length; i += 3) {
                const x = positions[i];
                const y = positions[i + 1];

                // Z (magasság) módosítása szinusz hullámokkal a folyékony hatásért
                positions[i + 2] = (Math.sin(x  0.5 + time  2.0) + Math.sin(y  0.8 + time  1.5))  0.05;
            }
            plane.geometry.attributes.position.needsUpdate = true; // Fontos!

            renderer.render(scene, camera);
        }


