            --text-muted: #94a3b8;
            --radius: 16px;
            --shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
            --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        html {
            height: 100%;
            height: -webkit-fill-available;
            scroll-behavior: smooth;
            -webkit-overflow-scrolling: touch;
        }

        body {
            font-family: 'Inter', sans-serif;
            background: var(--bg);
            color: var(--text);
            min-height: 100vh;
            min-height: -webkit-fill-available;
            overflow-x: hidden;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        /* Új 3D Liquid Háttér Stílus */
        #liquid-background {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: -1; /* A tartalom mögött van */
            display: block;
        }

        @supports (padding: max(0px)) {
            body {
                padding-left: max(0px, env(safe-area-inset-left));
                padding-right: max(0px, env(safe-area-inset-right));
            }
        }

        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb {
            background: var(--glass-strong);
            border-radius: 10px;
            border: 1px solid var(--border);
        }

        /* Régi Aurora háttér eltávolítva */
        .aurora-background { display: none; }

        /* --- Fő elrendezés --- */
        .container { 
            display: flex; 
            min-height: 100vh; 
            min-height: -webkit-fill-available;
            position: relative; 
            z-index: 2; /* A háttér fölött */
        }

        /* --- Oldalsáv (Sidebar) --- */
        .sidebar {
            width: 260px;
            background: var(--surface);
            backdrop-filter: blur(40px) saturate(180%);
            border-right: 1px solid var(--border);
            overflow-y: auto;
            position: fixed;
            height: 100vh;
            height: -webkit-fill-available;
            z-index: 1000;
            transform: translateX(-100%);
            transition: transform 0.4s var(--transition-curve);
            display: flex;
            flex-direction: column;
        }
        .sidebar.open { transform: translateX(0); }

        .sidebar-overlay {
            position: fixed;
            top: 0; left: 0;
            width: 100vw; height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(10px);
            z-index: 999;
            opacity: 0;
            visibility: hidden;
            transition: all 0.4s ease;
        }
        .sidebar-overlay.active { opacity: 1; visibility: visible; }

        .sidebar-header {
            padding: 16px 12px;
            border-bottom: 1px solid var(--border);
        }
        .logo { display: flex; align-items: center; gap: 8px; margin-bottom: 16px; }
        .logo-icon {
            width: 32px; height: 32px;
            background: var(--primary-gradient); /* Kék-NeonZöld Gradiens */
            border-radius: 8px;
            display: flex; align-items: center; justify-content: center;
            font-size: 1.2rem; font-weight: 800; color: #fff;
            box-shadow: 0 4px 20px rgba(10, 132, 255, 0.3), 0 4px 20px rgba(57, 255, 20, 0.3); /* Új árnyék */
            transition: transform 0.3s var(--transition-curve);
        }
        .logo:hover .logo-icon { transform: rotate(-10deg) scale(1.1); }
        .logo-text h1 {
            font-size: 1.2rem; font-weight: 800;
            color: var(--text);
            line-height: 1.1;
        }
        .logo-text p { font-size: 0.7rem; color: var(--text-muted); margin-top: 2px; font-weight: 500; }

        .new-chat-btn {
            width: 100%;
            background: var(--primary-gradient); /* Kék-NeonZöld Gradiens */
            border: none;
            color: #ffffff;
            border-radius: 10px;
            padding: 10px 12px;
            font-weight: 600; font-size: 0.8rem;
            cursor: pointer;
            display: flex; align-items: center; justify-content: center; gap: 6px;
            transition: all 0.3s var(--transition-curve);
            box-shadow: 0 6px 20px rgba(10, 132, 255, 0.3), 0 6px 20px rgba(57, 255, 20, 0.3); /* Új árnyék */
        }
        .new-chat-btn:hover, .new-chat-btn:active {
            transform: translateY(-2px);
            filter: brightness(1.1);
            box-shadow: 0 8px 25px rgba(10, 132, 255, 0.4), 0 8px 25px rgba(57, 255, 20, 0.4);
        }

        .sidebar-content { padding: 12px; flex-grow: 1; overflow-y: auto; }
        .sidebar-footer { padding: 12px; border-top: 1px solid var(--border); }
        .made-by { font-size: 0.7rem; color: var(--text-muted); text-align: center; }

        .service-category { margin-bottom: 16px; }
        .category-header {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius);
            padding: 8px 12px;
            cursor: pointer;
            display: flex; align-items: center; justify-content: space-between;
            margin-bottom: 6px;
            transition: all 0.3s var(--transition-curve);
            min-height: 40px;
        }
        .category-header .fa-chevron-down { transition: transform 0.3s var(--transition-curve); }
        .category-header:hover, .category-header:active {
            background: var(--glass-strong);
            border-color: var(--accent);
            transform: translateY(-2px);
        }
        .category-title { display: flex; align-items: center; gap: 8px; font-weight: 600; font-size: 0.8rem; }
        .category-title i { color: var(--accent); }
        .category-services {
            display: grid;
            grid-template-rows: 0fr;
            transition: grid-template-rows 0.4s ease-out;
        }
        .category-services > div { overflow: hidden; }
        .category-services.open { grid-template-rows: 1fr; }

        .service-item {
            background: transparent;
            border: 1px solid transparent;
            border-radius: var(--radius);
            padding: 8px 12px; margin-bottom: 4px; cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            display: flex; align-items: center; gap: 8px;
            margin-left: 0;
            border-left: 3px solid var(--border);
            min-height: 44px;
        }
        .service-item:hover, .service-item:active {
            background: var(--glass-strong);
            border-left-color: var(--accent);
            transform: translateX(4px);
            color: #fff;
            box-shadow: 0 0 15px var(--border-glow);
        }
        .service-icon {
            width: 24px; height: 24px;
            background: linear-gradient(135deg, var(--glass-strong), var(--glass));
            border: 1px solid var(--border);
            border-radius: 6px;
            display: flex; align-items: center; justify-content: center;
            font-size: 0.8rem; color: var(--accent); flex-shrink: 0;
            transition: all 0.3s var(--transition-curve);
        }
        .service-item:hover .service-icon { 
            transform: scale(1.1); 
            color: var(--accent); 
            border-color: var(--accent); 
        }
        .service-info h4 { font-size: 0.75rem; font-weight: 600; margin-bottom: 2px; }
        .service-info p { font-size: 0.7rem; color: var(--text-muted); }

        /* --- Fő tartalom --- */
        .main-content {
            flex: 1; margin-left: 0;
            display: flex; flex-direction: column;
            transition: margin-left 0.4s var(--transition-curve);
            min-height: 100vh;
            min-height: -webkit-fill-available;
        }
        .header {
            padding: 8px 16px;
            background: rgba(0, 0, 0, 0.6);
            backdrop-filter: blur(30px) saturate(150%);
            border-bottom: 1px solid var(--border);
            display: flex; align-items: center; justify-content: space-between;
            position: sticky; top: 0; z-index: 100;
            height: 56px;
        }
        .menu-toggle {
            background: var(--glass-strong);
            border: 1px solid var(--border);
            border-radius: 8px; padding: 8px;
            color: var(--text); cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            font-size: 0.9rem; width: 36px; height: 36px;
            display: flex; align-items: center; justify-content: center;
        }
        .menu-toggle:hover, .menu-toggle:active {
            background: var(--glass-strong);
            border-color: var(--accent);
            transform: scale(1.05);
        }
        .header-title {
            font-size: 1rem; font-weight: 700;
            color: var(--text);
            text-shadow: none;
        }

        /* --- Chat terület --- */
        .chat-area { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
        .messages-container { 
            flex: 1; 
            overflow-y: auto; 
            padding: 16px; 
            scroll-behavior: smooth;
            overscroll-behavior: contain;
        }

        .welcome-screen {
            text-align: center; max-width: 500px;
            margin: 0 auto; padding: 30px 16px;
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            height: 100%; animation: fadeIn 1s var(--transition-curve);
        }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .welcome-title {
            font-size: 2.5rem; font-weight: 800; margin-bottom: 1rem;
            color: var(--text);
            text-shadow: 0 0 30px var(--border-glow);
        }
        .welcome-subtitle { font-size: 1rem; color: var(--text-muted); margin-bottom: 2rem; line-height: 1.6; }
        .start-btn {
            background: var(--glass-strong);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: 12px 24px; color: var(--text);
            font-weight: 600; font-size: 0.9rem; cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            display: inline-flex; align-items: center; gap: 8px;
            min-height: 44px;
        }
        .start-btn:hover, .start-btn:active {
            background: var(--glass-strong);
            border-color: var(--accent);
            transform: translateY(-3px) scale(1.05);
        }

        /* Integrált design elemek a képekből */
        .design-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
            margin-top: 20px;
            padding: 20px;
        }
        .design-card {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius);
            padding: 16px;
            text-align: center;
            transition: all 0.3s var(--transition-curve);
        }
        .design-card:hover {
            transform: translateY(-5px);
            border-color: var(--accent);
            box-shadow: 0 0 20px var(--border-glow);
        }
        .design-image {
            width: 100%;
            height: 200px;
            object-fit: cover;
            border-radius: 8px;
            margin-bottom: 10px;
        }
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
            margin: 20px 0;
        }
        .stat-circle {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            background: var(--glass-strong);
            border: 2px solid var(--accent);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--accent);
            margin: 0 auto 10px;
        }
        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin-top: 20px;
        }
        .feature-card {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius);
            padding: 16px;
            text-align: center;
        }
        .feature-icon {
            font-size: 2rem;
            color: var(--secondary);
            margin-bottom: 10px;
        }
        .process-timeline {
            display: flex;
            justify-content: space-between;
            margin: 20px 0;
            padding: 0 20px;
        }
        .process-step {
            text-align: center;
            flex: 1;
        }
        .step-number {
            width: 40px;
            height: 40px;
            background: var(--primary-gradient);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: 700;
            margin: 0 auto 10px;
        }
        .tools-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
            gap: 10px;
            margin-top: 10px;
        }
        .tool-icon {
            width: 60px;
            height: 60px;
            background: var(--glass-strong);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 2rem;
            color: var(--accent);
        }
        .coding-section {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius);
            padding: 20px;
            margin-top: 20px;
            text-align: center;
        }
        .codient-logo {
            font-size: 3rem;
            background: var(--primary-gradient);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: 10px;
        }

        .message { margin-bottom: 16px; animation: messageSlideIn 0.5s var(--transition-curve); }
        @keyframes messageSlideIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

        .user-message { display: flex; justify-content: flex-end; }
        .user-bubble {
            background: var(--primary-gradient); /* Kék-NeonZöld Gradiens */
            color: #fff; padding: 10px 16px;
            border-radius: var(--radius) var(--radius) 4px var(--radius);
            max-width: 85%; font-weight: 500; font-size: 0.9rem; line-height: 1.5;
            box-shadow: 0 5px 20px rgba(10, 132, 255, 0.2), 0 5px 20px rgba(57, 255, 20, 0.2); /* Új árnyék */
        }
        .ai-message { display: flex; flex-direction: column; max-width: 95%; }
        .ai-content {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius) 4px var(--radius) var(--radius);
            padding: 12px 16px; line-height: 1.7; font-size: 0.9rem;
        }
        .ai-content pre {
            background: #010409;
            border: 1px solid var(--border);
            border-radius: 8px; padding: 12px; margin: 12px 0;
            font-size: 0.8rem; overflow-x: auto;
        }
        .ai-content code { font-family: 'SF Mono', 'Fira Code', 'Courier New', monospace; font-size: 0.8rem; }

        .message-actions { display: flex; gap: 6px; margin-top: 8px; margin-left: 8px; }
        .action-btn {
            background: var(--glass); border: 1px solid var(--border);
            border-radius: 6px; padding: 4px 8px; color: var(--text-muted);
            font-size: 0.7rem; cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            display: flex; align-items: center; gap: 4px;
            min-height: 32px;
        }
        .action-btn:hover, .action-btn:active {
            background: var(--glass-strong); color: var(--text);
            border-color: var(--accent); transform: translateY(-2px);
        }

        /* --- Beviteli mező --- */
        .input-area {
            padding: 16px;
            background: transparent;
            backdrop-filter: none;
            border-top: 1px solid var(--border);
            position: sticky; bottom: 0; z-index: 50;
        }

        @supports (padding: max(0px)) {
            .input-area {
                padding-bottom: max(16px, env(safe-area-inset-bottom));
            }
        }

        .input-wrapper { 
            max-width: 1000px; 
            margin: 0 auto; 
            display: flex; 
            gap: 8px; 
            align-items: flex-end;
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius);
            padding: 8px;
            transition: all 0.3s var(--transition-curve);
        }
        .input-wrapper:focus-within {
            border-color: var(--accent);
            box-shadow: 0 0 20px var(--border-glow);
        }

        .message-input {
            flex: 1; 
            background: transparent;
            border: none;
            border-radius: 8px;
            padding: 10px 14px; color: var(--text); font-size: 0.9rem;
            resize: none; outline: none;
            transition: all 0.3s var(--transition-curve);
            min-height: 40px; max-height: 120px;
            font-family: inherit; line-height: 1.4;
        }
        .message-input:focus {
            box-shadow: none;
        }
        .send-btn {
            width: 40px; height: 40px;
            background: var(--accent);
            border: none;
            border-radius: 12px;
            color: #fff; font-size: 1rem;
            cursor: pointer; transition: all 0.3s var(--transition-curve);
            display: flex; align-items: center; justify-content: center;
            box-shadow: 0 4px 15px var(--border-glow);
            flex-shrink: 0;
        }
        .send-btn:hover, .send-btn:active { 
            transform: scale(1.1); 
            box-shadow: 0 8px 25px rgba(10, 132, 255, 0.6); 
        }
        .send-btn:disabled {
            opacity: 0.5; cursor: not-allowed; transform: none;
            background: var(--glass-strong); border-color: var(--border);
            box-shadow: none;
        }

        /* --- Töltés és Visszajelzés --- */
        .typing-indicator { display: flex; gap: 6px; }
        .typing-dot {
            width: 6px; height: 6px;
            border-radius: 50%;
            animation: typing-bounce 1.4s infinite ease-in-out;
        }
        .typing-dot:nth-child(1) { background: var(--primary); }
        .typing-dot:nth-child(2) { background: var(--secondary); animation-delay: 0.2s; }
        .typing-dot:nth-child(3) { background: var(--primary); animation-delay: 0.4s; }

        @keyframes typing-bounce {
            0%, 80%, 100% { transform: scale(0); }
            40% { transform: scale(1.0); }
        }

        /* Deep Research Töltésjelző */
        .research-indicator {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius); 
            padding: 24px;
            display: flex; flex-direction: column; align-items: center; gap: 16px;
        }
        .research-indicator .spinner {
            width: 40px; height: 40px;
            border: 4px solid var(--border);
            border-top-color: var(--accent);
            border-radius: 50%;
            animation: spin 1s linear infinite;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        .research-indicator h4 { 
            font-weight: 600; 
            color: var(--text); 
            font-size: 1rem;
        }
        .research-indicator p { 
            font-size: 0.9rem;
            color: var(--text-muted); 
            text-align: center; 
        }

        /* --- Modális ablak (Modal) --- */
        .modal {
            position: fixed; top: 0; left: 0;
            width: 100%; height: 100%;
            background: rgba(0, 0, 0, 0.8);
            backdrop-filter: blur(15px);
            display: none; align-items: center; justify-content: center;
            z-index: 2000; opacity: 0;
            transition: opacity 0.3s ease; padding: 16px;
        }
        .modal.show { display: flex; opacity: 1; }
        .modal-content {
            background: var(--surface); border: 1px solid var(--border);
            border-radius: var(--radius); padding: 20px;
            max-width: 450px; width: 100%;
            max-height: 90vh; overflow-y: auto;
            backdrop-filter: blur(40px) saturate(180%);
            transform: scale(0.95) translateY(20px);
            transition: transform 0.4s var(--transition-curve);
        }
        .modal.show .modal-content { transform: scale(1) translateY(0); }
        .modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
        .modal-title {
            font-size: 1.2rem; font-weight: 700;
            color: var(--text);
        }
        .close-btn {
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: 50%; width: 32px; height: 32px;
            display: flex; align-items: center; justify-content: center;
            color: var(--text); cursor: pointer;
            transition: all 0.3s var(--transition-curve);
        }
        .close-btn:hover, .close-btn:active { transform: scale(1.1) rotate(90deg); }
        .modal-body { display: flex; flex-direction: column; gap: 12px; }
        .modal-body label { font-weight: 500; color: var(--text-muted); font-size: 0.8rem; }
        .modal-body input, .modal-body textarea {
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: 8px; padding: 10px; color: var(--text);
            font-size: 0.9rem; outline: none;
            transition: all 0.3s var(--transition-curve);
            font-family: inherit; resize: vertical;
        }
        .modal-body input:focus, .modal-body textarea:focus { border-color: var(--accent); }
        .modal-footer { margin-top: 20px; display: flex; justify-content: flex-end; }
        .modal-submit-btn {
            background: var(--accent); color: #fff;
            border: none; border-radius: 8px;
            padding: 10px 20px; font-weight: 600; font-size: 0.8rem;
            cursor: pointer; transition: all 0.3s var(--transition-curve);
            min-height: 40px;
        }
        .modal-submit-btn:hover, .modal-submit-btn:active { transform: translateY(-2px); }

        /* --- Kutatási Eredmények és Dokumentumok --- */
        .research-complete, .research-error {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius); padding: 20px; margin: 12px 0;
            backdrop-filter: blur(10px);
        }
        .completion-stats h3, .error-text h3 {
            font-weight: 700; margin-bottom: 12px;
            color: var(--text); font-size: 1rem;
            display: flex; align-items: center; gap: 8px;
        }
        .completion-stats h3 { color: var(--accent); }
        .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 12px; margin-bottom: 20px; }

        .stat-item { 
            text-align: center; 
            background: var(--glass-strong);
            padding: 16px; 
            border-radius: var(--radius); 
            border: 1px solid var(--border);
        }
        .stat-number { 
            display: block; 
            font-size: 1.5rem; 
            font-weight: 700; 
            color: var(--accent); 
        }
        .stat-label { font-size: 0.7rem; color: var(--text-muted); }

        .document-preview {
            background: linear-gradient(135deg, rgba(10, 132, 255, 0.1), rgba(10, 132, 255, 0.05));
            border: 1px solid var(--accent); border-radius: 10px;
            padding: 16px; cursor: pointer; transition: all 0.3s ease;
            display: flex; align-items: center; gap: 12px;
        }
        .document-preview:hover {
            background: linear-gradient(135deg, rgba(10, 132, 255, 0.2), rgba(10, 132, 255, 0.1));
            transform: translateY(-3px); box-shadow: 0 5px 15px rgba(10, 132, 255, 0.2);
        }
        .document-icon { font-size: 2rem; color: var(--accent); flex-shrink: 0; }
        .document-info h4 { margin: 0 0 4px 0; color: var(--text); font-weight: 600; font-size: 0.9rem; }
        .document-info p { margin: 0; color: var(--text-muted); font-size: 0.8rem; }
        .document-arrow { font-size: 1.2rem; color: var(--accent); margin-left: auto; flex-shrink: 0; transition: transform 0.3s ease; }
        .document-preview:hover .document-arrow { transform: translateX(5px); }

        .research-error { border-color: #ff3b30; }
        .error-text h3 { color: #ff453a; }
        .error-icon { font-size: 1rem; }

        .document-viewer {
            position: fixed; top: 0; left: 0;
            width: 100%; height: 100%;
            background: var(--bg); z-index: 10000;
            display: none; flex-direction: column;
            animation: slideInFromRight 0.5s var(--transition-curve);
        }
        @keyframes slideInFromRight { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .document-viewer.show { display: flex; }
        .document-header {
            background: rgba(0, 0, 0, 0.7);
            backdrop-filter: blur(30px);
            padding: 1rem; border-bottom: 1px solid var(--border);
            display: flex; align-items: center; gap: 1rem; flex-wrap: wrap;
        }
        .document-header h2 { flex: 1; margin: 0; font-weight: 700; font-size: 1.1rem; }
        .document-content { flex: 1; overflow-y: auto; padding: 1.5rem; }
        .document-section { margin-bottom: 2.5rem; }
        .document-section h3 {
            color: var(--accent); border-bottom: 2px solid var(--accent);
            padding-bottom: 0.5rem; margin-bottom: 1rem; font-weight: 700; font-size: 1rem;
        }
        .synthesis-content { 
            line-height: 1.7; 
            background: var(--surface);
            padding: 1rem; 
            border-radius: 6px; 
            border-left: 4px solid var(--accent); 
        }
        .source-item {
            display: flex; gap: 0.8rem; padding: 0.8rem;
            background: var(--surface);
            border-radius: 6px;
            margin-bottom: 0.8rem; border-left: 3px solid var(--border);
            transition: all 0.3s ease;
        }
        .source-item:hover { border-left-color: var(--accent); transform: translateX(5px); }
        .source-number { color: var(--accent); font-weight: bold; flex-shrink: 0; }
        .source-content h4 { margin: 0 0 0.5rem 0; font-size: 0.9rem; }
        .source-content a { color: var(--accent); text-decoration: none; font-size: 0.8rem; word-break: break-all; }
        .source-content a:hover { text-decoration: underline; }
        .source-date { display: block; color: var(--text-muted); font-size: 0.7rem; margin-top: 0.5rem; }

        /* iOS-szerű animációk és interakciók */
        .ios-bounce {
            animation: iosBounce 0.3s ease-out;
        }

        @keyframes iosBounce {
            0% { transform: scale(1); }
            50% { transform: scale(0.95); }
            100% { transform: scale(1); }
        }

        /* Érintési visszajelzés */
        .touch-feedback {
            position: relative;
            overflow: hidden;
        }

        .touch-feedback::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            background: rgba(255, 255, 255, 0.3);
            border-radius: 50%;
            transform: translate(-50%, -50%);
            transition: width 0.3s ease, height 0.3s ease;
            pointer-events: none;
        }

        .touch-feedback.active::before {
            width: 200px;
            height: 200px;
        }

        /* Swipe indikátor */
        .swipe-indicator {
            position: fixed;
            top: 50%;
            left: 10px;
            transform: translateY(-50%);
            width: 4px;
            height: 60px;
            background: var(--accent);
            border-radius: 2px;
            opacity: 0;
            transition: opacity 0.3s ease;
            z-index: 1000;
        }

        .swipe-indicator.show {
            opacity: 0.7;
        }

        /* Pull-to-refresh indikátor */
        .pull-refresh {
            position: fixed;
            top: -60px;
            left: 50%;
            transform: translateX(-50%);
            width: 40px;
            height: 40px;
            background: var(--glass);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: top 0.3s ease;
            z-index: 1000;
        }

        .pull-refresh.active {
            top: 20px;
        }

        .pull-refresh svg {
            width: 20px;
            height: 20px;
            color: var(--accent);
            animation: spin 1s linear infinite;
        }

        /* Gomb pressed állapot */
        .btn-pressed {
            transform: scale(0.95) !important;
            opacity: 0.8 !important;
        }

        /* Mobil nézet optimalizációk */
        @media (max-width: 768px) {
            .sidebar { width: 240px; }
            .header-title { font-size: 0.9rem; }
            .messages-container, .input-area { padding: 12px; }
            .document-header { padding: 0.8rem; flex-direction: column; align-items: stretch; }
            .document-header h2 { text-align: center; margin: 0.8rem 0; }
            .document-content { padding: 1rem; }
            .welcome-title { font-size: 2rem; }
            .welcome-subtitle { font-size: 0.9rem; }
            .design-grid { grid-template-columns: 1fr; }
            .stats-grid { grid-template-columns: 1fr; }
            .features-grid { grid-template-columns: 1fr; }
            .process-timeline { flex-direction: column; gap: 20px; }

            .input-area {
                padding: 8px 12px;
                @supports (padding: max(0px)) {
                    padding-bottom: max(8px, env(safe-area-inset-bottom));
                }
            }
            .input-wrapper { padding: 6px; }
            .message-input { padding: 8px 10px; min-height: 36px; }
            .send-btn { width: 36px; height: 36px; }
        }

        /* Nagyon kicsi mobil eszközökre */
        @media (max-width: 480px) {
            .sidebar { width: 220px; }
            .header { padding: 6px 12px; height: 48px; }
            .header-title { font-size: 0.8rem; }
            .menu-toggle { width: 32px; height: 32px; font-size: 0.8rem; }
            .send-btn { width: 32px; height: 32px; }
            .message-input { font-size: 0.8rem; min-height: 32px; }
            .input-area { 
                padding: 8px 12px; 
                @supports (padding: max(0px)) {
                    padding-bottom: max(8px, env(safe-area-inset-bottom));
                }
            }
            .welcome-title { font-size: 1.8rem; }
            .welcome-subtitle { font-size: 0.8rem; }
            .user-bubble { font-size: 0.8rem; }
            .ai-content { font-size: 0.8rem; }
        }
    </style>
</head>
<body>
