    <!-- Dokumentum Megjelenítő -->
    <div class="document-viewer" id="documentViewer" role="document" aria-hidden="true">
        <div class="document-header">
            <button class="action-btn back-button touch-feedback" onclick="closeDocumentViewer()">
                <i class="fas fa-arrow-left"></i> Vissza
            </button>
            <h2 id="documentTitle">Kutatási Dokumentum</h2>
            <div class="document-actions">
                <button class="action-btn touch-feedback"><i class="fas fa-download"></i> Letöltés</button>
                <button class="action-btn touch-feedback"><i class="fas fa-share-alt"></i> Megosztás</button>
            </div>
        </div>
        <div class="document-content" id="documentContent"></div>
