    <script>
        // --- Globális Állapot és Konfiguráció ---
        const AppState = {
            isTyping: false,
            userId: 'user_' + Math.random().toString(36).substr(2, 9),
            researchState: null
        };
        const API_BASE_URL = '/api';

        // --- DOM Elemek Gyors Elérése ---
        const getEl = (id) => document.getElementById(id);

        // --- ÚJ 3D FOLYÉKONY HÁTTÉR ---
        let scene, camera, renderer, plane, lightBlue, lightGreen;
        let time = 0;

        function initLiquidBackground() {
            try {
                scene = new THREE.Scene();
                camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
                camera.position.z = 1.5;

                renderer = new THREE.WebGLRenderer({ canvas: getEl('liquid-background'), alpha: true });
                renderer.setSize(window.innerWidth, window.innerHeight);

                // A "folyékony" sík
                const geometry = new THREE.PlaneGeometry(5, 5, 100, 100);
                const material = new THREE.MeshStandardMaterial({
                    color: 0x000000, // Fekete alap, a fények adják a színt
                    metalness: 0.9,
                    roughness: 0.3,
                });
                plane = new THREE.Mesh(geometry, material);
                scene.add(plane);

                // Fények
                lightBlue = new THREE.PointLight(0x0A84FF, 5, 10);
                lightBlue.position.set(-1, -1, 1);
                scene.add(lightBlue);

                lightGreen = new THREE.PointLight(0x39FF14, 5, 10);
                lightGreen.position.set(1, 1, 1);
                scene.add(lightGreen);

                // Eszközkezelő az átméretezéshez
                window.addEventListener('resize', onWindowResize, false);

                // Animáció indítása
                animate();
            } catch (e) {
                console.error("3D background initialization failed:", e);
                // Hiba esetén elrejti a canvas-t, hogy ne legyen üres fekete blokk
                getEl('liquid-background').style.display = 'none';
            }
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function animate() {
            requestAnimationFrame(animate);
            time += 0.002; // Nagyon lassú animáció

            // Fények lassú mozgatása
            lightBlue.position.x = Math.sin(time * 0.3) * 2;
            lightBlue.position.y = Math.cos(time * 0.2) * 2;
            lightGreen.position.x = Math.sin(time * 0.2) * -2;
            lightGreen.position.y = Math.cos(time * 0.3) * -2;

            // Sík pontjainak (vertices) mozgatása a "liquid" effektért
            const positions = plane.geometry.attributes.position.array;
            for (let i = 0; i < positions.length; i += 3) {
                const x = positions[i];
                const y = positions[i + 1];

                // Z (magasság) módosítása szinusz hullámokkal a folyékony hatásért
                positions[i + 2] = (Math.sin(x * 0.5 + time * 2.0) + Math.sin(y * 0.8 + time * 1.5)) * 0.05;
            }
            plane.geometry.attributes.position.needsUpdate = true; // Fontos!

            renderer.render(scene, camera);
        }

        // iOS-szerű haptikus visszajelzés
        class HapticFeedback {
            static light() {
                if ('vibrate' in navigator) {
                    navigator.vibrate(10);
                }
            }
            static medium() { if ('vibrate' in navigator) { navigator.vibrate(20); } }
            static heavy() { if ('vibrate' in navigator) { navigator.vibrate([30, 10, 30]); } }
            static success() { if ('vibrate' in navigator) { navigator.vibrate([10, 50, 10]); } }
            static error() { if ('vibrate' in navigator) { navigator.vibrate([100, 50, 100, 50, 100]); } }
        }

        // Érintési gesztusok kezelése
        class TouchGestureHandler {
            constructor() {
                this.touchStartX = 0;
                this.touchStartY = 0;
                this.touchEndX = 0;
                this.touchEndY = 0;
                this.minSwipeDistance = 50;
                this.setupGestures();
            }

            setupGestures() {
                document.addEventListener('touchstart', (e) => {
                    this.touchStartX = e.changedTouches[0].screenX;
                    this.touchStartY = e.changedTouches[0].screenY;
                });

                document.addEventListener('touchend', (e) => {
                    this.touchEndX = e.changedTouches[0].screenX;
                    this.touchEndY = e.changedTouches[0].screenY;
                    this.handleSwipe();
                });

                // Pull-to-refresh kezelés
                let startY = 0;
                let currentY = 0;
                let isPulling = false;

                document.addEventListener('touchstart', (e) => {
                    startY = e.touches[0].clientY;
                    isPulling = true;
                });

                document.addEventListener('touchmove', (e) => {
                    if (!isPulling) return;
                    currentY = e.touches[0].clientY;
                    const diff = currentY - startY;
                    if (diff > 0 && getEl('messagesContainer').scrollTop === 0) {
                        getEl('pullRefresh').style.top = Math.min(20, diff / 3) + 'px';
                        getEl('pullRefresh').classList.add('active');
                        e.preventDefault();
                    }
                });

                document.addEventListener('touchend', () => {
                    isPulling = false;
                    getEl('pullRefresh').classList.remove('active');
                    getEl('pullRefresh').style.top = '-60px';
                    if (currentY - startY > 100) {
                        // Refresh logika
                        location.reload();
                        HapticFeedback.success();
                    }
                    startY = 0;
                    currentY = 0;
                });
            }

            handleSwipe() {
                const diffX = this.touchEndX - this.touchStartX;
                const diffY = this.touchEndY - this.touchStartY;
                if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > this.minSwipeDistance) {
                    if (diffX > 0) {
                        // Swipe jobbra - pl. következő oldal
                        getEl('swipeIndicator').classList.add('show');
                        setTimeout(() => getEl('swipeIndicator').classList.remove('show'), 1000);
                        HapticFeedback.light();
                    } else {
                        // Swipe balra - pl. előző oldal vagy sidebar
                        toggleSidebar();
                    }
                }
            }
        }

        // Alapfunkciók
        function toggleSidebar() {
            const sidebar = getEl('sidebar');
            const overlay = getEl('sidebarOverlay');
            sidebar.classList.toggle('open');
            overlay.classList.toggle('active');
            if (sidebar.classList.contains('open')) {
                overlay.addEventListener('click', closeSidebar);
                HapticFeedback.medium();
            }
        }

        function closeSidebar() {
            getEl('sidebar').classList.remove('open');
            getEl('sidebarOverlay').classList.remove('active');
        }

        function newChat() {
            // Új chat logika
            console.log('Új beszélgetés indítása');
            HapticFeedback.success();
        }

        function hideWelcome() {
            getEl('welcomeScreen').style.display = 'none';
            HapticFeedback.success();
        }

        function sendMessage() {
            const input = getEl('messageInput');
            const text = input.value.trim();
            if (!text || AppState.isTyping) return;
            input.value = '';
            // Üzenet hozzáadása
            addMessage(text, 'user');
            AppState.isTyping = true;
            // AI válasz szimuláció
            setTimeout(() => {
                addMessage('Ez egy AI válasz a kérdésre.', 'ai');
                AppState.isTyping = false;
            }, 1500);
            HapticFeedback.light();
        }

        function addMessage(text, sender) {
            const container = getEl('messagesContainer');
            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${sender}-message`;
            if (sender === 'user') {
                messageDiv.innerHTML = `<div class="user-bubble">${text}</div>`;
            } else {
                messageDiv.innerHTML = `<div class="ai-content">${text}</div>`;
            }
            container.appendChild(messageDiv);
            container.scrollTop = container.scrollHeight;
        }

        function closeModal() {
            getEl('serviceModal').classList.remove('show');
        }

        function closeDocumentViewer() {
            getEl('documentViewer').classList.remove('show');
        }

        // Eseménykezelők
        getEl('messageInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        getEl('sendBtn').addEventListener('click', sendMessage);

        // Inicializálás
        document.addEventListener('DOMContentLoaded', () => {
            initLiquidBackground();
            new TouchGestureHandler();
            // Szolgáltatások betöltése (szimuláció)
            loadServices();
            hljs.highlightAll();
        });

        function loadServices() {
            const content = getEl('sidebarContent');
            content.innerHTML = `
                <div class="service-category">
                    <div class="category-header" onclick="toggleCategory(this)">
                        <div class="category-title">
                            <i class="fas fa-robot"></i>
                            AI Szolgáltatások
                        </div>
                        <i class="fas fa-chevron-down"></i>
                    </div>
                    <div class="category-services">
                        <div>
                            <div class="service-item" onclick="selectService('deep-research')">
                                <div class="service-icon"><i class="fas fa-search"></i></div>
                                <div class="service-info">
                                    <h4>Deep Research</h4>
                                    <p>Mély elemzés</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            `;
        }

        function toggleCategory(header) {
            const services = header.nextElementSibling;
            services.classList.toggle('open');
            header.querySelector('.fa-chevron-down').style.transform = services.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)';
            HapticFeedback.light();
        }

        function selectService(id) {
            // Szolgáltatás kiválasztása
            console.log('Kiválasztott szolgáltatás:', id);
            closeSidebar();
            // Pl. modális megnyitása
            openServiceModal(id);
        }

        function openServiceModal(id) {
            const modal = getEl('serviceModal');
            const body = getEl('modalBody');
            const footer = getEl('modalFooter');
            const title = getEl('modalTitle');
            if (id === 'deep-research') {
                title.textContent = 'Deep Research';
                body.innerHTML = `
                    <label for="query">Keresési lekérdezés:</label>
                    <input type="text" id="query" placeholder="Pl. 'AI trendek 2025'">
                    <label for="depth">Mélység:</label>
                    <select id="depth">
                        <option value="basic">Alap</option>
                        <option value="deep">Mély</option>
                    </select>
                `;
                footer.innerHTML = `<button class="modal-submit-btn" onclick="startResearch()">Kutatni</button>`;
            }
            modal.classList.add('show');
        }

        function startResearch() {
            const query = getEl('query').value;
            if (!query) return;
            // Kutatási indítás
            AppState.researchState = 'running';
            showResearchIndicator(query);
            closeModal();
            HapticFeedback.heavy();
        }

        function showResearchIndicator(query) {
            const container = getEl('messagesContainer');
            const indicator = document.createElement('div');
            indicator.className = 'research-indicator';
            indicator.innerHTML = `
                <div class="spinner"></div>
                <h4>Kutatás folyamatban...</h4>
                <p>${query} témában gyűjtjük az adatokat.</p>
            `;
            container.appendChild(indicator);
            container.scrollTop = container.scrollHeight;
            // Szimulált befejezés
            setTimeout(() => {
                showResearchComplete();
            }, 3000);
        }

        function showResearchComplete() {
            const container = getEl('messagesContainer');
            const lastChild = container.lastElementChild;
            if (lastChild && lastChild.classList.contains('research-indicator')) {
                lastChild.remove();
            }
            const complete = document.createElement('div');
            complete.className = 'research-complete';
            complete.innerHTML = `
                <h3><i class="fas fa-check-circle"></i> Kutatás Befejezve</h3>
                <div class="stats-grid">
                    <div class="stat-item">
                        <span class="stat-number">12</span>
                        <span class="stat-label">Dokumentum</span>
                    </div>
                    <div class="stat-item">
                        <span class="stat-number">45</span>
                        <span class="stat-label">Forrás</span>
                    </div>
                    <div class="stat-item">
                        <span class="stat-number">3.2</span>
                        <span class="stat-label">Oldal</span>
                    </div>
                </div>
                <div class="document-preview" onclick="openDocument()">
                    <i class="fas fa-file-alt document-icon"></i>
                    <div class="document-info">
                        <h4>Kutatás Összefoglaló</h4>
                        <p>AI trendek elemzése 2025-re</p>
                    </div>
                    <i class="fas fa-arrow-right document-arrow"></i>
                </div>
            `;
            container.appendChild(complete);
            container.scrollTop = container.scrollHeight;
            AppState.researchState = 'complete';
        }

        function openDocument() {
            getEl('documentViewer').classList.add('show');
            getEl('documentContent').innerHTML = `
                <div class="document-section">
                    <h3>Összefoglaló</h3>
                    <div class="synthesis-content">
                        <p>A kutatás során 12 releváns dokumentumot találtunk, amelyek kiemelik a 2025-ös AI trendeket, beleértve a neurális hálózatok fejlődését és etikai kérdéseket.</p>
                    </div>
                </div>
                <div class="document-section">
                    <h3>Források</h3>
                    <div class="source-item">
                        <span class="source-number">1.</span>
                        <div class="source-content">
                            <h4>AI Trends 2025 Report</h4>
                            <a href="#">https://example.com/report.pdf</a>
                            <span class="source-date">2025-10-01</span>
                        </div>
                    </div>
                </div>
            `;
            HapticFeedback.medium();
        }

        // Touch feedback animációk
        document.querySelectorAll('.touch-feedback').forEach(el => {
            el.addEventListener('touchstart', () => el.classList.add('active', 'ios-bounce'));
            el.addEventListener('touchend', () => {
                setTimeout(() => el.classList.remove('active', 'ios-bounce'), 300);
            });
        });

        // Sidebar overlay esemény
        function initOverlay() {
            getEl('sidebarOverlay').addEventListener('click', closeSidebar);
        }
        initOverlay();
    </script>
</body>
</html>
